   frames,ids=decode(row['metadata'],ds);assert ids==cap['frame_ids'];pos=cap['positions8'];ck,context=evidence_key(frames[pos],row['metadata']['caption'],positions=pos,frame_ids=ids,fingerprint=runtime,dataset=ds);hits=[root for root in roots if(root/(ck+'.json')).exists()];assert hits;root=hits[0];meta=read(root/(ck+'.json'));assert meta['key']==ck and meta['context']==context and sha(root/(ck+'.pt'))==meta['sha256'];teacher=torch.load(root/(ck+'.pt'),map_location='cpu',weights_only=False,mmap=True)
